 "content": "from collections import Counter


def transform(grid):
    """Repeat the most populated non-background panel across matching panels."""
    h, w = len(grid), len(grid[0])
    global_bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_seps = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != global_bg]
    col_seps = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != global_bg]

    def segments(n, separators):
        result, start = [], 0
        for pos in separators:
            if start < pos:
                result.append((start, pos))
            start = pos + 1
        if start < n:
            result.append((start, n))
        return result

    row_segments = segments(h, row_seps)
    col_segments = segments(w, col_seps)
    panels = []
    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            bg = Counter(v for row in panel for v in row).most_common(1)[0][0]
            score = sum(v != bg for row in panel for v in row)
            panels.append((score, panel))

    source = max(panels, key=lambda item: item[0])[1]
    out = [row[:] for row in grid]
    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            if r1 - r0 == len(source) and c1 - c0 == len(source[0]):
                for dr in range(len(source)):
                    out[r0 + dr][c0:c1] = source[dr][:]
    return out
